update ticket_tiers set
    ticket_permit = ticket_permit - #{ticketBuyDTO.count},
    ticket_lock = ticket_lock + #{ticketBuyDTO.count}
where
    event_session_id = #{ticketBuyDTO.eventSessionId}
    and ticket_level = #{ticketBuyDTO.ticketLevel}
    and ticket_permit >= #{ticketBuyDTO.count}

UPDATE ticket_tiers SET
    ticket_permit = ticket_permit + #{ticketTotal},
    ticket_lock = ticket_lock - #{ticketTotal}
WHERE
    event_session_id = #{eventSessionId}
    and ticket_level = #{ticketLevel}
    and ticket_lock >= #{ticketTotal}

UPDATE ticket_tiers SET
    ticket_lock = ticket_lock - #{ticketTotal}
WHERE
    event_session_id = #{eventSessionId}
  and ticket_level = #{ticketLevel}
  and ticket_lock >= #{ticketTotal}
